<details class="border-b border-slate-100 px-5 py-3"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Ver datos específicos, recursos y resultado</summary><dl class="mt-4 grid gap-4 sm:grid-cols-2"><?php foreach ($definition['fields'] as $field): $val=$record['datos'][$field['name']]??''; if ($field['type']==='employee'&&$val) { foreach ($employees as $employee) if ((int)$employee['id']===(int)$val) $val=$employee['nombre'].' · '.$employee['documento']; } ?><div><dt class="text-[10px] uppercase tracking-wide text-slate-400"><?= e($field['label']) ?></dt><dd class="mt-1 whitespace-pre-line text-xs leading-5 text-slate-700"><?= $val===''||$val===null?'—':e($val) ?></dd></div><?php endforeach; ?><div><dt class="text-[10px] uppercase text-slate-400">Recursos</dt><dd class="mt-1 whitespace-pre-line text-xs text-slate-700"><?= e($record['recursos']?:'—') ?></dd></div><div><dt class="text-[10px] uppercase text-slate-400">Resultado</dt><dd class="mt-1 whitespace-pre-line text-xs text-slate-700"><?= e($record['resultado']?:'Sin resultado registrado') ?></dd></div></dl></details>
